"""Verify the actual reader with the fixture generated by create_fixture.py."""

from pathlib import Path
import os
import json
import struct
import subprocess
import sys
from tempfile import TemporaryDirectory

from PIL import Image
from playwright.sync_api import expect, sync_playwright


ROOT = Path(__file__).resolve().parents[1]
BASE = "http://127.0.0.1:" + os.getenv("CSTR_PORT", "4173")
COMIC = BASE + "/library/order-fixture.cstr"
CHROME = os.getenv("CSTR_CHROME")


def verify_reader_limits(browser, folder):
    cli = [sys.executable, str(ROOT / "pack.py")]
    big = folder / "large.png"
    comic = folder / "large.cstr"
    with Image.new("RGB", (6000, 6000), "white") as image:
        image.save(big)
    subprocess.run(cli + ["-o", str(comic), str(big)], check=True)
    reader = browser.new_page(viewport={"width": 1280, "height": 2300})
    reader.goto(BASE)
    reader.locator("#file").set_input_files(comic)
    expect(reader.locator("[data-chunk='0'] canvas")).to_be_visible()
    expect(reader.locator("[data-chunk='1'] canvas")).to_be_visible()

    with Image.new("RGB", (4600, 4600), "white") as image:
        image.save(big)
    subprocess.run(cli + ["-o", str(comic), str(big), str(big)], check=True)
    reader.reload()
    reader.locator("#file").set_input_files(comic)
    expect(reader.locator("[data-chunk='0'] canvas")).to_be_visible()
    expect(reader.locator("[data-chunk='1'] canvas")).to_be_visible()
    reader.close()

    with Image.new("RGB", (10, 10), "blue") as image:
        image.save(big)
    metadata = folder / "metadata.json"
    metadata.write_text(json.dumps({"title": "x" * 70000}), encoding="utf-8")
    subprocess.run(cli + ["--metadata", str(metadata), "-o", str(comic), str(big)], check=True)
    data = comic.read_bytes()
    index_start, index_size, meta_size = struct.unpack_from("<QII", data, 16)
    payload_start = index_start + index_size + meta_size
    remote_url = BASE + "/library/metadata-unavailable.cstr"
    held_payload = []
    remote = browser.new_page()

    def handle_range(route):
        start, end = map(int, route.request.headers["range"].removeprefix("bytes=").split("-"))
        if start == payload_start:
            held_payload.append(route)
        elif start == 65536:
            route.fulfill(status=503, body="Metadata unavailable")
        else:
            fulfill_range(route, start, end)

    def fulfill_range(route, start, end):
        end = min(end, len(data) - 1)
        route.fulfill(status=206, headers={"Content-Range": f"bytes {start}-{end}/{len(data)}"},
                      body=data[start:end + 1])

    remote.route(remote_url, handle_range)
    remote.goto(BASE)
    remote.get_by_label("漫画包链接").fill(remote_url)
    remote.get_by_role("button", name="打开链接").click()
    expect(remote.locator("#notice")).to_contain_text("503")
    assert len(held_payload) == 1
    fulfill_range(held_payload[0], payload_start, len(data) - 1)
    expect(remote.locator("[data-chunk='0'] canvas")).to_be_visible()
    remote.close()


with sync_playwright() as playwright:
    browser = playwright.chromium.launch(executable_path=CHROME, headless=True)
    try:
        screen = browser.new_page(viewport={"width": 1280, "height": 900})
        errors = []
        responses = []
        screen.on("pageerror", lambda error: errors.append(str(error)))
        screen.on("response", lambda response: responses.append(response) if response.url == COMIC else None)
        screen.goto(BASE)
        screen.wait_for_load_state("networkidle")
        expect(screen.get_by_role("heading", name="打开漫画")).to_be_visible()
        screen.screenshot(path=ROOT / ".cache" / "test" / "desktop.png")

        screen.get_by_label("漫画包链接").fill(COMIC)
        screen.get_by_role("button", name="打开链接").click()
        expect(screen.locator("[data-chunk='0'] canvas")).to_be_visible(timeout=15000)
        expect(screen.locator("#book-title")).to_have_text("排序测试")
        assert responses[0].status == 206
        assert responses[0].request.headers["range"] == "bytes=0-65535"
        assert responses[1].request.headers["range"].startswith("bytes=65536-")
        assert all(response.status == 206 for response in responses)
        assert len(responses) < 9
        assert screen.locator("section[data-page]").evaluate_all(
            "(pages) => pages.map(page => [...page.children].map(chunk => +chunk.dataset.chunk))"
        ) == [[0, 1, 2], [3, 4, 5], [6, 7, 8]]

        page_number = screen.get_by_role("spinbutton", name="跳到第几页")
        page_number.fill("3")
        page_number.press("Enter")
        expect(page_number).to_have_value("3")
        expect(screen.locator("[data-chunk='6'] canvas")).to_be_visible(timeout=15000)
        screen.locator("#viewport").evaluate("(viewport) => viewport.scrollTop = viewport.scrollHeight")
        assert screen.locator("section[data-page='3']").evaluate(
            "(page) => page.getBoundingClientRect().bottom > document.querySelector('#viewport').getBoundingClientRect().top"
        )
        screen.get_by_role("button", name="上一页").click()
        expect(page_number).to_have_value("2")
        expect(screen.locator("[data-chunk='3'] canvas")).to_be_visible(timeout=15000)
        assert not errors, errors

        parallel = browser.new_page(viewport={"width": 1280, "height": 4200})
        held = []

        def reorder(route):
            start = route.request.headers["range"].split("=")[1].split("-")[0]
            if start == "65536":
                held.append(route)
            else:
                route.continue_()

        parallel.route(COMIC, reorder)
        parallel.goto(BASE)
        parallel.get_by_label("漫画包链接").fill(COMIC)
        parallel.get_by_role("button", name="打开链接").click()
        # Blocks 0–2 are held while page 2 is decoded.
        expect(parallel.locator("[data-chunk='3'] canvas")).to_be_visible(timeout=15000)
        assert len(held) == 1
        assert parallel.locator("[data-chunk='0'] canvas").count() == 0
        held.pop().continue_()
        expect(parallel.locator("[data-chunk='0'] canvas")).to_be_visible(timeout=15000)
        for chunk, color in ((0, [240, 40, 40]), (3, [40, 220, 60])):
            pixel = parallel.locator(f"[data-chunk='{chunk}'] canvas").evaluate("""image => {
                const surface = document.createElement('canvas');
                const context = surface.getContext('2d');
                context.drawImage(image, 0, 0);
                return Array.from(context.getImageData(0, 0, 1, 1).data).slice(0, 3);
            }""")
            assert pixel == color, (chunk, pixel)

        mobile = browser.new_page(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True)
        mobile.goto(BASE)
        mobile.wait_for_load_state("networkidle")
        assert mobile.locator("body").evaluate("(body) => body.scrollWidth === window.innerWidth")
        mobile.screenshot(path=ROOT / ".cache" / "test" / "mobile.png")
        mobile.locator("#file").set_input_files(ROOT / "library" / "order-fixture.cstr")
        expect(mobile.locator("[data-chunk='0'] canvas")).to_be_visible(timeout=15000)
        expect(mobile.locator("#book-title")).to_have_text("排序测试")
        mobile.get_by_role("button", name="下一页").click()
        expect(mobile.get_by_role("spinbutton")).to_have_value("2")
        expect(mobile.locator("[data-chunk='3'] canvas")).to_be_visible(timeout=15000)
        mobile.screenshot(path=ROOT / ".cache" / "test" / "mobile-reader.png")
        with TemporaryDirectory() as temporary:
            verify_reader_limits(browser, Path(temporary))
    finally:
        browser.close()
print("PASS: Chromium Range playback, out-of-order blocks, jump, mobile navigation, large pages and metadata recovery.")
